    private static PortalBreadcrumbItem CreateQueriesOverviewCrumb(
        IReadOnlyList<PortalMenuDto> queryMenus,
        string currentPath)
    {
        var moduleLinks = new List<PortalBreadcrumbLink>();
        foreach (var group in queryMenus.GroupBy(i => i.ParentName.AsString().Trim()))
        {
            PortalMenuDto? firstPage = null;
            foreach (var menu in group.OrderBy(i => FormatMenuItemTitle(i)))
            {
                if (string.IsNullOrWhiteSpace(menu.ActionName))
                    continue;

                firstPage = menu;
                break;
            }

            if (firstPage == null)
                continue;

            moduleLinks.Add(new PortalBreadcrumbLink(
                FormatSectionTitle(group.Key),
                firstPage.ActionName,
                group.Any(i => IsActivePath(currentPath, i.ActionName))));
        }

        moduleLinks.Sort((left, right) => string.Compare(left.Text, right.Text, StringComparison.OrdinalIgnoreCase));

        return new PortalBreadcrumbItem
        {
            Text = "Live Reports",
            Url = moduleLinks.FirstOrDefault()?.Url,
            RelatedLinks = moduleLinks
        };
    }

    private static PortalBreadcrumbItem CreateQueryModuleCrumb(
        string moduleLabel,
        IReadOnlyList<PortalMenuDto> moduleQueryPages,
        string currentPath)
    {
        var tableLinks = new List<PortalBreadcrumbLink>();
        foreach (var group in moduleQueryPages
                     .Select(menu =>
                     {
                         TryGetQueryMenuParts(menu, out var table, out _);
                         return (Menu: menu, Table: table);
                     })
                     .Where(x => !string.IsNullOrWhiteSpace(x.Table))
                     .GroupBy(x => x.Table, StringComparer.OrdinalIgnoreCase))
        {
            PortalMenuDto? firstPage = null;
            foreach (var entry in group.OrderBy(x => FormatMenuItemTitle(x.Menu)))
            {
                if (string.IsNullOrWhiteSpace(entry.Menu.ActionName))
                    continue;

                firstPage = entry.Menu;
                break;
            }

            if (firstPage == null)
                continue;

            tableLinks.Add(new PortalBreadcrumbLink(
                group.Key.SplitCamelCaseToString(),
                firstPage.ActionName,
                group.Any(x => IsActivePath(currentPath, x.Menu.ActionName))));
        }

        tableLinks.Sort((left, right) => string.Compare(left.Text, right.Text, StringComparison.OrdinalIgnoreCase));

        return new PortalBreadcrumbItem
        {
            Text = moduleLabel,
            Url = tableLinks.FirstOrDefault()?.Url
                  ?? moduleQueryPages.FirstOrDefault(i => !string.IsNullOrWhiteSpace(i.ActionName))?.ActionName,
            RelatedLinks = tableLinks
        };
    }

